1	using Gatekeeper.Web.Components;
2	using Gatekeeper.Web.Components.Account;
3	using Gatekeeper.Web.Data;
4	using Gatekeeper.Web.Services;
5	using Microsoft.AspNetCore.Components.Authorization;
6	using Microsoft.AspNetCore.Identity;
7	using Microsoft.EntityFrameworkCore;
8	
9	var builder = WebApplication.CreateBuilder(args);
10	
11	// Add services to the container.
12	builder.Services.AddRazorComponents()
13	    .AddInteractiveServerComponents(options => options.DetailedErrors = builder.Environment.IsDevelopment());
14	
15	builder.Services.AddCascadingAuthenticationState();
16	builder.Services.AddScoped<IdentityUserAccessor>();
17	builder.Services.AddScoped<IdentityRedirectManager>();
18	builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();
19	
20	builder.Services.AddAuthentication(options =>
21	    {
22	        options.DefaultScheme = IdentityConstants.ApplicationScheme;
23	        options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
24	    })
25	    .AddIdentityCookies();
26	
27	var connectionString = builder.Configuration.GetConnectionString("DefaultConnection")
28	    ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
29	
30	// Use a factory so interactive Blazor components can create short-lived contexts per
31	// operation instead of sharing one context for the whole circuit.
32	builder.Services.AddDbContextFactory<GatekeeperDbContext>(options =>
33	    options.UseNpgsql(connectionString));
34	// ASP.NET Core Identity's stores need a scoped context; bridge it off the factory.
35	builder.Services.AddScoped<GatekeeperDbContext>(sp =>
36	    sp.GetRequiredService<IDbContextFactory<GatekeeperDbContext>>().CreateDbContext());
37	builder.Services.AddDatabaseDeveloperPageExceptionFilter();
38	
39	builder.Services.AddIdentityCore<ApplicationUser>(options => options.SignIn.RequireConfirmedAccount = false)
40	    .AddEntityFrameworkStores<GatekeeperDbContext>()
41	    .AddSignInManager()
42	    .AddDefaultTokenProviders();
43	
44	builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();
45	
46	// Gatekeeper application services.
47	builder.Services.AddScoped<IAuditLogger, AuditLogger>();
48	
49	var app = builder.Build();
50	
51	// ADR-0051: say what this is, every time it boots.
52	Gatekeeper.Web.LabTargetBanner.Log(
53	    app.Services.GetRequiredService<ILoggerFactory>().CreateLogger("Gatekeeper.LabTarget"),
54	    app.Environment.ContentRootPath);
55	
56	// Configure the HTTP request pipeline.
57	if (app.Environment.IsDevelopment())
58	{
59	    app.UseMigrationsEndPoint();
60	}
61	else
62	{
63	    app.UseExceptionHandler("/Error", createScopeForErrors: true);
64	    // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
65	    app.UseHsts();
66	}
67	
68	app.UseHttpsRedirection();
69	
70	app.UseStaticFiles();
71	app.UseAntiforgery();
72	
