curl -s -o /dev/null -w "put status=%{http_code}\n" -X PUT "$BASE/api/policy" -H 'Content-Type: application/json' -d '{
  "roles": [ { "name": "Auditors", "parent": null } ],
  "assignments": [ { "subject": "alice", "role": "Auditors" } ],
  "grants": [
    { "subject": "alice",    "action": "record:purge", "resource": "*",      "effect": "Allow" },
    { "subject": "Auditors", "action": "record:purge", "resource": "ledger", "effect": "Deny"  }
  ]
}'
decide() { echo -n "  "; curl -s -X POST "$BASE/api/decisions" -H 'Content-Type: application/json' -d "$1"; echo "   <= $1"; }
echo "=== decisions ==="
decide '{"subject":"alice","action":"record:purge","resource":"ledger"}'
decide '{"subject":"alice","action":"record:purge","resource":"other"}'

